@SubscribeEvent
    public static void PotionRemoveEvents(MobEffectEvent.Remove event){
        LivingEntity effected = event.getEntity();
        if (effected != null) {
            if (event.getEffect() != null) {
                if (effected.hasEffect(GoetyEffects.SAVE_EFFECTS.get())) {
                    event.setCanceled(event.getEffect() != GoetyEffects.SAVE_EFFECTS.get()
                            && (effected instanceof Player player
                            && SEHelper.hasEndWalk(player)
                            && event.getEffect() != GoetyEffects.SHADOW_WALK.get()));
                }
                if (event.getEffect() != null) {
                    if (event.getEffect() == GoetyEffects.SHADOW_WALK.get()) {
                        if (effected instanceof Player player) {
                            teleportShadowWalk(player);
                        }
                    }
                }
                if (event.getEffect() == GoetyEffects.WILD_RAGE.get()){
                    if (effected instanceof Mob mob) {
                        mob.setTarget(null);
                        mob.setLastHurtByMob(null);
                        mob.getBrain().eraseMemory(MemoryModuleType.ANGRY_AT);
                        mob.getBrain().eraseMemory(MemoryModuleType.ATTACK_TARGET);
                    }
                }
                if (event.getEffect() == GoetyEffects.VOID_TOUCHED.get()){
                    if (effected.level instanceof ServerLevel) {
                        ModNetwork.sentToTrackingEntityAndPlayer(effected, new SPlayWorldSoundPacket(effected.blockPosition(), ModSounds.VOID_TOUCHED_DEACTIVATE.get(), 1.0F, 1.0F));
                    }
                }
                if (event.getEffect() == GoetyEffects.ENCHANTED.get()) {
                    if (effected.level instanceof ServerLevel) {
                        MiscCapHelper.setEnchanter(effected, null);
                    }
                }
            }
        }
    }

@SubscribeEvent
    public static void PotionExpiredEvents(MobEffectEvent.Expired event){
        LivingEntity effected = event.getEntity();
        MobEffectInstance mobEffectInstance = event.getEffectInstance();
        if (mobEffectInstance != null) {
            if (mobEffectInstance.getEffect() == GoetyEffects.SHADOW_WALK.get()) {
                if (effected instanceof Player player) {
                    teleportShadowWalk(player);
                }
            }

            if (mobEffectInstance.getEffect() == GoetyEffects.DOOM.get()){
                if (effected.canChangeDimensions() && !effected.getType().is(Tags.EntityTypes.BOSSES)) {
                    int a = mobEffectInstance.getAmplifier() + 1;
                    float doom = 0.05F * a;
                    if (effected.getHealth() <= effected.getMaxHealth() * doom) {
                        effected.hurt(ModDamageSource.getDamageSource(effected.level, ModDamageSource.DOOM), effected.getMaxHealth() * 20);
                    }
                }
            }

            if (mobEffectInstance.getEffect() == GoetyEffects.VOID_TOUCHED.get()){
                if (effected.level instanceof ServerLevel) {
                    ModNetwork.sentToTrackingEntityAndPlayer(effected, new SPlayWorldSoundPacket(effected.blockPosition(), ModSounds.VOID_TOUCHED_DEACTIVATE.get(), 1.0F, 1.0F));
                }
            }
            if (mobEffectInstance.getEffect() == GoetyEffects.ENCHANTED.get()) {
                if (effected.level instanceof ServerLevel) {
                    MiscCapHelper.setEnchanter(effected, null);
                }
            }
        }
    }

@Override
    public void SpellResult(ServerLevel worldIn, LivingEntity caster, ItemStack staff, SpellStat spellStat) {
        int potency = spellStat.getPotency();
        int duration = spellStat.getDuration();
        if (WandUtil.enchantedFocus(caster)){
            potency += WandUtil.getPotencyLevel(caster);
            duration = MathHelper.secondsToTicks(5) * WandUtil.getLevels(ModEnchantments.DURATION.get(), caster);
        }
        if (caster instanceof Player player){
            player.addEffect(new MobEffectInstance(GoetyEffects.SHADOW_WALK.get(), SpellConfig.EndWalkEffectDuration.get() + duration, potency, false, false, true));
            for(int i = 0; i < 16; ++i) {
                double d0 = MathHelper.rgbToSpeed(96.0D);
                double d1 = MathHelper.rgbToSpeed(62.0D);
                double d2 = MathHelper.rgbToSpeed(92.0D);
                worldIn.sendParticles(ModParticleTypes.CULT_SPELL.get(), caster.getRandomX(1.0D), caster.getRandomY(), caster.getRandomZ(1.0D), 0, d0, d1, d2, 0.5F);
            }
            SEHelper.setEndWalk(player, player.blockPosition(), player.level.dimension());
            ModNetwork.sendTo(player, new SPlayPlayerSoundPacket(ModSounds.END_WALK.get(), 1.0F, 1.0F));
        }
    }

protected void teleport() {
        if (!this.level.isClientSide() && !this.isNoAi() && this.isAlive() && this.toTeleportPos == null && !this.isSettingUpSecond() && !this.isCasting()) {
            if (MobsConfig.ApostleDelayedTeleport.get()) {
                if (this.pendingTeleportSearch != null) {
                    if (this.pendingTeleportSearch.isDone()) {
                        final double startY = this.getTarget() != null ? this.getTarget().getY() : this.getY();
                        Vec3 result = this.pendingTeleportSearch.getNow(null);
                        this.pendingTeleportSearch = null;
                        Vec3 vec3 = findTeleportGroundY(this.level, result.x, result.y + 3, result.z, startY);
                        if (vec3 != null) {
                            this.toTeleportPos = vec3;
                            this.playSound(ModSounds.APOSTLE_PRE_TELEPORT.get(), 2.0F, 1.0F);
                            this.resetHitTime();
                        }
                    }
                } else {
                    final double startX = this.getX();
                    final double startY = this.getTarget() != null ? this.getTarget().getY() : this.getY();
                    final double startZ = this.getZ();
                    final RandomSource randomSource = this.apostleRandom;

                    this.prevX = startX;
                    this.prevY = this.getY();
                    this.prevZ = startZ;

                    this.pendingTeleportSearch = CompletableFuture.supplyAsync(() -> {
                        double d0 = 32.0D;
                        double d1 = startX + (randomSource.nextDouble() - 0.5D) * d0;
                        double d2 = startY + 3.0D;
                        double d3 = startZ + (randomSource.nextDouble() - 0.5D) * d0;
                        return new Vec3(d1, d2, d3);
                    });
                }
            } else {
                for (int i = 0; i < 128; ++i) {
                    double d3 = this.getX() + (this.level.getRandom().nextDouble() - 0.5D) * 32.0D;
                    double d4 = this.getTarget() != null ? this.getTarget().getY() : this.getY();
                    double d5 = this.getZ() + (this.level.getRandom().nextDouble() - 0.5D) * 32.0D;
                    BlockPos blockPos = BlockPos.containing(d3, d4, d5);
                    boolean flag = this.getTarget() == null || i >= 64 || BlockFinder.canSeeBlock(this.getTarget(), blockPos);
                    if (flag && this.randomTeleport(d3, d4, d5, false)) {
                        this.teleportHits();
                        this.resetHitTime();
                        break;
                    }
                }
            }
        }
    }

